// @db.nullable（dbNullable）の列では、値のないスライスとマップも NULL。
func (c dbCol) Value() (driver.Value, error) {
	v := reflect.ValueOf(c.v)
	switch v.Kind() {
	case reflect.Pointer:
		if v.IsNil() {
			return nil, nil
		}
		v = v.Elem()
	case reflect.Slice, reflect.Map:
		if v.IsNil() && slices.Contains(c.opts, dbNullable) {
			return nil, nil
		}
	}
	return c.write(v)
}

// Scan は、列の値 src を、読む先に読む。NULL は、@db.nullable（dbNullable）の列でだけ読めて、読む先は、値がない（nil）。
// ほかの列に NULL があれば、エラー。読む先がポインタ（省略可能）かどうかは、実行時に見る。
func (c dbCol) Scan(src any) error {
	dst := reflect.ValueOf(c.v).Elem()
	if src == nil {
		if !slices.Contains(c.opts, dbNullable) {
			return fmt.Errorf("db: NULL in a column without @db.nullable (read into %s)", dst.Type())
		}
		dst.SetZero()
		return nil
	}
	if dst.Kind() == reflect.Pointer {
		dst.Set(reflect.New(dst.Type().Elem()))
		dst = dst.Elem()
	}
	return c.read(src, dst)
}

// dbArgs は、列の並びを、文に渡す値の並びにする。
func dbArgs(cols ...dbCol) ([]any, error) {
	args := make([]any, len(cols))
	for i, c := range cols {
		v, err := c.Value()
		if err != nil {
			return nil, err
		}
		args[i] = v
	}
	return args, nil
}

// dbString は、列の値 src を文字列として読む。
func dbString(src any) (string, error) {
	var s sql.NullString
	err := s.Scan(src)
	return s.String, err
}

// dbText は @db.text の列: 文字列を、そのまま。
func dbText(v any, opts ...dbOption) dbCol {
	return dbCol{v, opts, func(v reflect.Value) (driver.Value, error) {
		return v.String(), nil
	}, func(src any, dst reflect.Value) error {
		s, err := dbString(src)
		if err != nil {
			return err
		}
		dst.SetString(s)
		return nil
	}}
}

// dbInt は @db.int の列: 整数を、そのまま（Duration は、ナノ秒の数）。
func dbInt(v any, opts ...dbOption) dbCol {
	return dbCol{v, opts, func(v reflect.Value) (driver.Value, error) {
		return v.Int(), nil
	}, func(src any, dst reflect.Value) error {
		var n sql.NullInt64
		if err := n.Scan(src); err != nil {
			return err
		}
		dst.SetInt(n.Int64)
		return nil
	}}
}

// dbBool は @db.bool の列: 真偽値を、0 か 1 の整数で。
func dbBool(v any, opts ...dbOption) dbCol {
	return dbCol{v, opts, func(v reflect.Value) (driver.Value, error) {
		if v.Bool() {
			return int64(1), nil
		}
		return int64(0), nil
	}, func(src any, dst reflect.Value) error {
		var b sql.NullBool
		if err := b.Scan(src); err != nil {
			return err
		}
		dst.SetBool(b.Bool)
		return nil
	}}
}

// dbTimeLayout は @db.time の列の形: RFC 3339、UTC、小数部はいつも 9 桁（文字列の順が時刻の順になる）。
const dbTimeLayout = "2006-01-02T15:04:05.000000000Z07:00"

// dbTime は @db.time の列: 時刻を、dbTimeLayout の文字列で。
func dbTime(v any, opts ...dbOption) dbCol {
	return dbCol{v, opts, func(v reflect.Value) (driver.Value, error) {
		t := v.Convert(reflect.TypeFor[time.Time]()).Interface().(time.Time)
		return t.UTC().Format(dbTimeLayout), nil
	}, func(src any, dst reflect.Value) error {
		s, err := dbString(src)
		if err != nil {
			return err
		}
		t, err := time.Parse(time.RFC3339Nano, s)
		if err != nil {
			return err
		}
		dst.Set(reflect.ValueOf(t).Convert(dst.Type()))
		return nil
	}}
}

// dbJSON は @db.json の列: 値を、encoding/json の JSON の文字列で。
func dbJSON(v any, opts ...dbOption) dbCol {
	return dbCol{v, opts, func(v reflect.Value) (driver.Value, error) {
		data, err := json.Marshal(v.Interface())
		return string(data), err
	}, func(src any, dst reflect.Value) error {
		s, err := dbString(src)
		if err != nil {
			return err
		}
		return json.Unmarshal([]byte(s), dst.Addr().Interface())
	}}
}

// dbExec は行を返さない文を実行する。
func dbExec(ctx context.Context, db *sql.DB, query string, args ...any) error {
	_, err := db.ExecContext(ctx, query, args...)
	return err
}

// dbIsEmpty は、行の数を返す問い合わせの結果が 0 かどうか。
func dbIsEmpty(ctx context.Context, db *sql.DB, query string) (bool, error) {
	var n int64
	if err := db.QueryRowContext(ctx, query).Scan(&n); err != nil {
		return false, err
	}
	return n == 0, nil
}

// dbGet は問い合わせの一行を scan で読む。行がなければ nil。
func dbGet[R any](ctx context.Context, db *sql.DB, scan func(dbRow) (R, error), query string, args ...any) (*R, error) {
	row, err := scan(db.QueryRowContext(ctx, query, args...))
	if errors.Is(err, sql.ErrNoRows) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	return &row, nil
}

// dbList は問い合わせのすべての行を scan で読む。
func dbList[R any](ctx context.Context, db *sql.DB, scan func(dbRow) (R, error), query string, args ...any) ([]R, error) {
	rows, err := db.QueryContext(ctx, query, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []R
	for rows.Next() {
		row, err := scan(rows)
		if err != nil {
			return nil, err
		}
		out = append(out, row)
	}
	return out, rows.Err()
}
